import{_ as t,c as o,o as r,af as l}from"./chunks/framework.BKeRpnBD.js";const q=JSON.parse('{"title":"易經歷史與傳承","description":"易經歷史與傳承，整理自 App 的免費易經學習文檔。","frontmatter":{"title":"易經歷史與傳承","description":"易經歷史與傳承，整理自 App 的免費易經學習文檔。"},"headers":[],"relativePath":"articles/history/index.md","filePath":"articles/history/index.md"}'),i={name:"articles/history/index.md"};function e(n,a,s,h,p,u){return r(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="《易經》探源-八卦的生成脈絡與中華文明的精神坐標" tabindex="-1">《易經》探源：八卦的生成脈絡與中華文明的精神坐標 <a class="header-anchor" href="#《易經》探源-八卦的生成脈絡與中華文明的精神坐標" aria-label="Permalink to “《易經》探源：八卦的生成脈絡與中華文明的精神坐標”">​</a></h1><p>在中華典籍的璀璨星河中，《周易》始終佔據著獨一無二的核心位置。這部常被稱作《易經》的古籍，不僅是已知中國最古老的經典之一，更因貫穿數千年的思想深度與文化廣度，被歷代學者尊為 “群經之首、大道之源”。它並非某一時代、某一位賢者的孤作，而是遠古先民到先秦諸子共同熔鑄的智慧結晶，其從原始自然觀測到成熟哲學體系的演變，本身就是一部濃縮的早期中華文明史。</p><h3 id="一、八卦濫觴-先民對宇宙秩序的原始解碼" tabindex="-1">一、八卦濫觴：先民對宇宙秩序的原始解碼 <a class="header-anchor" href="#一、八卦濫觴-先民對宇宙秩序的原始解碼" aria-label="Permalink to “一、八卦濫觴：先民對宇宙秩序的原始解碼”">​</a></h3><p>八卦作為《周易》的符號根基，其源頭可追溯至公元前 3000 年左右的新石器時代晚期。彼時人類尚未形成系統文字，卻已開始以敬畏之心探索自然與自身的關聯。傳說人文始祖伏羲氏在黃河之濱 “觀象授時”—— 他仰望蒼穹記錄日月星辰的運轉軌跡，俯瞰大地辨識山川走向與草木枯榮，從四季更迭、晝夜交替的規律中，提煉出八種支配宇宙的基本力量。</p><p>於是伏羲以 “—”（陽爻）象徵剛健、主動的能量，以 “--”（陰爻）代表柔婉、被動的特質，組合成乾（天）、坤（地）、震（雷）、巽（風）、坎（水）、離（火）、艮（山）、兌（澤）八卦。這組極簡的線條符號，不僅是先民對自然現象的具象概括，更暗含 “天人合一” 的原始哲學思維 —— 他們相信，天地間的一切變化，皆可通過八卦的組合與推演找到規律，這為後世《周易》的發展埋下了思想種子。</p><h3 id="二、薪火相傳-從三代易書到哲學經典的蛻變" tabindex="-1">二、薪火相傳：從三代易書到哲學經典的蛻變 <a class="header-anchor" href="#二、薪火相傳-從三代易書到哲學經典的蛻變" aria-label="Permalink to “二、薪火相傳：從三代易書到哲學經典的蛻變”">​</a></h3><p>八卦符號體系並非一成不變，而是在夏、商、週三代的更迭中不斷豐富，形成了脈絡清晰的發展軌跡：</p><ul><li><p><strong>夏代・《連山》</strong>：作為已知最早的易書，《連山》以 “艮卦” 為首（“艮” 象徵山）。夏族崛起於黃河流域的山地之間，對山林有著深厚的崇拜之情，這部典籍的卦序設置，既反映了夏人對山川地理的依賴，也記錄了當時與農耕、祭祀相關的占卜經驗，是指導先民生產生活的實用工具。</p></li><li><p><strong>商代・《歸藏》</strong>：商人取代夏朝後，將易書發展為《歸藏》，改以 “坤卦” 為首（“坤” 代表地）。商人重視土地耕種與祖先祭祀，且社會仍保留母系文化殘餘，“坤” 的核心地位，既體現對土地孕育萬物的感恩，也暗含對女性祖先的尊崇，其內容在《連山》基礎上，更側重吉凶禍福的解讀，與商代發達的龜甲占卜文化深度融合。</p></li><li><p><strong>周代・《周易》成熟</strong>：西周初年，周文王姬昌被商紂王囚禁於羑里時，在夏商易書基礎上，將八卦兩兩相疊推演為六十四卦，每卦配以簡短卦辭，讓符號體繫有了更豐富的語義內涵。此後周公旦為闡釋卦理，創作《彖傳》（解讀卦辭主旨）與《象傳》（從卦象引申處世之道），將易理與周代禮樂制度、倫理規範相結合。</p></li></ul><p>到春秋末期，孔子晚年對《周易》痴迷至 “韋編三絕”（因反復翻閱導致竹簡編繩斷裂三次），他與弟子在原有內容基礎上補充《文言》《繫辭》《說卦》等 “十翼” 篇章 ——“十翼” 如同為《周易》插上翅膀，徹底將其從佔筮之書昇華為哲學經典，通過闡釋 “陰陽辯證”“剛柔相濟” 的道理，賦予典籍宇宙觀、人生觀與價值觀的深度，使其成為儒家思想的重要源頭。</p><h3 id="三、文脈根基-貫穿千年的文化影響力" tabindex="-1">三、文脈根基：貫穿千年的文化影響力 <a class="header-anchor" href="#三、文脈根基-貫穿千年的文化影響力" aria-label="Permalink to “三、文脈根基：貫穿千年的文化影響力”">​</a></h3><p>《周易》的價值從未侷限於古籍本身，而是滲透到中華文明的方方面面，成為塑造民族思維方式的精神基因：</p><ul><li><p><strong>思想層面</strong>：其 “陰陽相生”“天人合一” 理念，搭建了中國傳統哲學的核心框架 —— 儒家從 “乾道成男，坤道成女” 引申出倫理秩序，強調 “中庸” 與 “修身治國”；道家從 “道生一，一生二” 汲取靈感，發展出 “道法自然” 的宇宙觀，二者共同構成傳統思想的兩大支柱。</p></li><li><p><strong>文學藝術</strong>：八卦符號與卦辭意象成為歷代創作的重要素材：杜甫以 “乾坤日夜浮” 描繪洞庭壯闊，蘇軾用 “坎離更用抽添象” 暗喻人生變化；繪畫書法則借鑒八卦的對稱美與線條韻律，追求 “虛實相生” 的東方美學境界。</p></li><li><p><strong>政治與社會</strong>：“窮則變，變則通” 的理念成為王朝改革的理論依據，“自強不息”（乾卦）、“厚德載物”（坤卦）則塑造了傳統士人的品格追求，影響著治國理政的邏輯與社會倫理的構建。</p></li><li><p><strong>科學領域</strong>：中醫陰陽五行學說直接源於《周易》辯證思想，強調人體與自然的平衡；古代天文曆法、數學演算也常以八卦為推演工具，如漢代張衡渾天儀設計、宋代沈括對天文現象的解讀，皆可見易理痕跡。</p></li></ul><p>即便在現代，《周易》的辯證思維仍為管理學、心理學提供東方智慧，成為全球研究中華文化的重要切入點。它早已不是一部單純的古籍，而是中華文明的 “精神坐標”，記錄著先民對世界的認知，也指引著後人對智慧的永恆追求。</p><hr><h1 id="《易經》古代傳承譜系-主要流派與代表人物解析" tabindex="-1">《易經》古代傳承譜系：主要流派與代表人物解析 <a class="header-anchor" href="#《易經》古代傳承譜系-主要流派與代表人物解析" aria-label="Permalink to “《易經》古代傳承譜系：主要流派與代表人物解析”">​</a></h1><p>自《周易》經傳成型後，歷代學者對其闡釋從未停歇。因時代思潮、治學方法差異，逐漸形成了風格迥異的傳統流派 —— 這些流派或重符號推演，或重哲理闡發，或融百家思想，共同構築了《易經》千年傳承的學術版圖。從漢代的象數之學，到魏晉的義理之辯，再到宋明的哲學融合，每一流派的興起都與當時的文化語境深度綁定，而代表人物的著作與思想，更成為易學傳承的關鍵節點。</p><h3 id="一、象數派-以符號推演為核心-貫通天人之理-漢至唐" tabindex="-1">一、象數派：以符號推演為核心，貫通天人之理（漢至唐） <a class="header-anchor" href="#一、象數派-以符號推演為核心-貫通天人之理-漢至唐" aria-label="Permalink to “一、象數派：以符號推演為核心，貫通天人之理（漢至唐）”">​</a></h3><p>象數派是《易經》最早形成的流派之一，核心主張以 “象”（卦象、爻象）與 “數”（陰陽數、天地數）解讀易理，強調易學與天文、曆法、占卜的關聯，尤其在漢代成為官方易學主流，與當時 “天人感應” 的思潮相呼應。</p><h4 id="_1-漢代今文易學-京房與-納甲飛伏-說" tabindex="-1">1. 漢代今文易學：京房與 “納甲飛伏” 說 <a class="header-anchor" href="#_1-漢代今文易學-京房與-納甲飛伏-說" aria-label="Permalink to “1. 漢代今文易學：京房與 “納甲飛伏” 說”">​</a></h4><ul><li><p><strong>代表人物</strong>：京房（西漢，前 77 - 前 37），字君明，漢代今文易學的關鍵人物，雖因捲入政治鬥爭早逝，卻為象數派奠定了系統理論。</p></li><li><p><strong>核心主張</strong>：在傳統八卦基礎上，創立 “納甲說”—— 將十天干、十二地支對應八卦六爻，使卦象與天文曆法結合；提出 “飛伏說”，認為每卦皆有 “飛爻”（顯現之爻）與 “伏爻”（隱藏之爻），二者相互作用，可推演事物吉凶變化。他還將六十四卦分為 “八宮”，每宮統八卦，形成更精密的占卜體系。</p></li><li><p><strong>影響</strong>：京房的象數理論讓《易經》從哲學典籍轉向實用占卜工具，對後世術數（如八字、風水）影響深遠，其著作《京氏易傳》至今仍是研究漢代易學的重要文獻。</p></li></ul><h4 id="_2-漢代古文易學-鄭玄與-爻辰-注易" tabindex="-1">2. 漢代古文易學：鄭玄與 “爻辰” 注易 <a class="header-anchor" href="#_2-漢代古文易學-鄭玄與-爻辰-注易" aria-label="Permalink to “2. 漢代古文易學：鄭玄與 “爻辰” 注易”">​</a></h4><ul><li><p><strong>代表人物</strong>：鄭玄（東漢，127-200），字康成，漢代經學集大成者，雖非純然象數派，卻以古文經學視角豐富了象數解讀。</p></li><li><p><strong>核心主張</strong>：創立 “爻辰說”，將六十四卦三百八十四爻與十二時辰、二十八星宿對應，試圖從天文星象角度闡釋卦爻辭的起源；同時融合今古文易學，既重視象數推演，也不忽視義理內涵，其注易著作兼採眾長，被譽為 “鄭學”。</p></li><li><p><strong>影響</strong>：鄭玄的注本成為魏晉前易學的權威讀本，打破了今古文易學的對立，為象數派注入了更多學術性。</p></li></ul><h4 id="_3-唐代象數傳承-孔穎達與官修《周易正義》" tabindex="-1">3. 唐代象數傳承：孔穎達與官修《周易正義》 <a class="header-anchor" href="#_3-唐代象數傳承-孔穎達與官修《周易正義》" aria-label="Permalink to “3. 唐代象數傳承：孔穎達與官修《周易正義》”">​</a></h4><ul><li><p><strong>代表人物</strong>：孔穎達（唐代，574-648），字衝遠，唐代經學家，主持編纂《五經正義》，其中《周易正義》是唐代官方易學的標桿。</p></li><li><p><strong>核心主張</strong>：以漢代象數派為基礎，兼採魏晉義理派觀點，主張 “象為義之本”—— 先明卦象之理，再闡發義理內涵，試圖調和象數與義理的矛盾。其注本以王弼《周易注》為底本，卻補充了大量漢代象數解讀，避免了純義理的空疏。</p></li><li><p><strong>影響</strong>：《周易正義》成為唐代科舉考試的標準教材，使象數派的核心理論得以官方傳承，也為宋代理學易學埋下了 “融合象義” 的伏筆。</p></li></ul><h3 id="二、義理派-以哲學闡發為核心-剝離象數附會-魏晉至宋明" tabindex="-1">二、義理派：以哲學闡發為核心，剝離象數附會（魏晉至宋明） <a class="header-anchor" href="#二、義理派-以哲學闡發為核心-剝離象數附會-魏晉至宋明" aria-label="Permalink to “二、義理派：以哲學闡發為核心，剝離象數附會（魏晉至宋明）”">​</a></h3><p>義理派興起於魏晉，反對漢代象數派過度注重占卜、牽強附會的傾向，主張以儒家倫理、道家思想解讀《易經》，將其還原為哲學經典。這一流派在宋明時期達到鼎盛，與理學、心學深度融合，成為中國傳統哲學的重要載體。</p><h4 id="_1-魏晉玄學易學-王弼與-得意忘象" tabindex="-1">1. 魏晉玄學易學：王弼與 “得意忘象” <a class="header-anchor" href="#_1-魏晉玄學易學-王弼與-得意忘象" aria-label="Permalink to “1. 魏晉玄學易學：王弼與 “得意忘象””">​</a></h4><ul><li><p><strong>代表人物</strong>：王弼（三國魏，226-249），字輔嗣，魏晉玄學的開創者之一，雖年僅 24 歲去世，卻以《周易注》重構了易學闡釋路徑。</p></li><li><p><strong>核心主張</strong>：提出 “得意忘象，得象忘言”—— 認為卦象（象）是表達義理（意）的工具，語言（言）是描述卦象的工具，解讀《易經》應透過象與言，直抵義理本質，反對漢代學者 “拘於象數而失義理” 的做法。他以道家 “無為之理” 釋易，將 “太極” 解讀為 “無”，使易學與玄學思想相通。</p></li><li><p><strong>影響</strong>：王弼《周易注》徹底扭轉了易學發展方向，使義理派成為主流，其 “得意忘象” 說至今仍是易學闡釋的重要方法論。</p></li></ul><h4 id="_2-宋代理學易學-程頤與-以儒釋易" tabindex="-1">2. 宋代理學易學：程頤與 “以儒釋易” <a class="header-anchor" href="#_2-宋代理學易學-程頤與-以儒釋易" aria-label="Permalink to “2. 宋代理學易學：程頤與 “以儒釋易””">​</a></h4><ul><li><p><strong>代表人物</strong>：程頤（北宋，1033-1107），字正叔，理學創始人之一，其著作《伊川易傳》是宋代義理派的經典。</p></li><li><p><strong>核心主張</strong>：將《易經》與儒家倫理緊密結合，主張 “易道即天道，天道即人道”—— 認為卦爻辭中的吉凶悔吝，本質是 “天理” 對人事的指引，學習《易經》的目的是 “窮理盡性”，而非占卜吉凶。他反對王弼的道家傾向，強調 “理” 是易學的核心，如以 “乾為剛健” 對應儒家 “自強不息” 的品格，以 “坤為柔順” 對應 “厚德載物” 的德行。</p></li><li><p><strong>影響</strong>：程頤的易學使義理派從玄學回歸儒家正統，為宋明理學提供了重要的哲學依據，其 “即事窮理” 的方法也影響了後世儒家治學路徑。</p></li></ul><h4 id="_3-宋代理學集大成-朱熹與《周易本義》" tabindex="-1">3. 宋代理學集大成：朱熹與《周易本義》 <a class="header-anchor" href="#_3-宋代理學集大成-朱熹與《周易本義》" aria-label="Permalink to “3. 宋代理學集大成：朱熹與《周易本義》”">​</a></h4><ul><li><p><strong>代表人物</strong>：朱熹（南宋，1130-1200），字元晦，理學集大成者，其《周易本義》是後世影響最廣的易學著作之一。</p></li><li><p><strong>核心主張</strong>：調和象數與義理，認為 “象數乃義理之根基，義理乃象數之歸宿”—— 既承認八卦符號的原始意義（如伏羲先天八卦的象數價值），又強調需通過義理闡發其道德內涵。他將《周易》分為 “經”（卦爻辭）與 “傳”（十翼），主張先讀 “經” 以明象數，再讀 “傳” 以明義理，反對 “離象言義” 或 “離義言象” 的極端。</p></li><li><p><strong>影響</strong>：《周易本義》成為明清科舉考試的標準注本，其 “象義結合” 的觀點至今仍是主流易學觀點，朱熹也被視為義理派的集大成者。</p></li></ul><h4 id="_4-明代心學易學-王陽明與-心即易理" tabindex="-1">4. 明代心學易學：王陽明與 “心即易理” <a class="header-anchor" href="#_4-明代心學易學-王陽明與-心即易理" aria-label="Permalink to “4. 明代心學易學：王陽明與 “心即易理””">​</a></h4><ul><li><p><strong>代表人物</strong>：王陽明（明代，1472-1529），字伯安，心學創始人，其易學思想散見於《傳習錄》《五經臆說》中，雖未留下專門易注，卻開創了 “心學易學” 流派。</p></li><li><p><strong>核心主張</strong>：提出 “心即理，理即易”—— 認為《易經》的義理不在書本，而在人的本心，“八卦不過是吾心之常道”，如 “乾之剛健” 即本心的 “良知”，“坤之柔順” 即本心的 “誠意”。他反對脫離本心空談易理，主張 “在事上磨練”，通過踐行良知來體認易理。</p></li><li><p><strong>影響</strong>：王陽明的心學易學將易學從 “外在天理” 拉回到 “內在本心”，為義理派注入了主觀能動性，對明代中後期的思想解放有重要推動作用。</p></li></ul><h3 id="三、圖書派-以圖式為核心-推演宇宙規律-宋至元" tabindex="-1">三、圖書派：以圖式為核心，推演宇宙規律（宋至元） <a class="header-anchor" href="#三、圖書派-以圖式為核心-推演宇宙規律-宋至元" aria-label="Permalink to “三、圖書派：以圖式為核心，推演宇宙規律（宋至元）”">​</a></h3><p>圖書派是宋代興起的特殊流派，核心主張《易經》起源於 “河圖”“洛書”（傳說中伏羲得自黃河、洛水的圖式），認為八卦、六十四卦皆由圖書衍生而來，注重以圖式推演宇宙生成規律，是象數派在宋代的新形態。</p><h4 id="代表人物-邵雍與-先天八卦圖" tabindex="-1">代表人物：邵雍與 “先天八卦圖” <a class="header-anchor" href="#代表人物-邵雍與-先天八卦圖" aria-label="Permalink to “代表人物：邵雍與 “先天八卦圖””">​</a></h4><ul><li><p><strong>邵雍（北宋，1011-1077）</strong>，字堯夫，號安樂先生，圖書派的創始人，其著作《皇極經世》以圖書易學為基礎，構建了龐大的宇宙觀體系。</p></li><li><p><strong>核心主張</strong>：提出 “先天八卦” 與 “後天八卦” 之分 —— 認為伏羲所創為 “先天八卦”（以乾南坤北、離東坎西為序），反映宇宙本然的陰陽規律；周文王所演為 “後天八卦”（以離南坎北、震東兌西為序），反映天地人互動的人事規律。他以 “先天圖” 為核心，結合 “元會運世” 的時間單位，推演宇宙從生成到毀滅的循環過程，試圖用易理解釋天地萬物的起源與變化。</p></li><li><p><strong>影響</strong>：邵雍的圖書易學雖帶有一定神秘色彩，卻為《易經》增添了宇宙論維度，其先天八卦圖至今仍是易學、術數領域的重要圖式，對後世天文學、數學也有間接影響。</p></li></ul><h3 id="四、結語-流派紛呈背後的易學生命力" tabindex="-1">四、結語：流派紛呈背後的易學生命力 <a class="header-anchor" href="#四、結語-流派紛呈背後的易學生命力" aria-label="Permalink to “四、結語：流派紛呈背後的易學生命力”">​</a></h3><p>《易經》古代流派的演變，本質是不同時代學者對 “何為易理” 的持續追問：象數派重 “天道規律”，試圖以符號連接天人；義理派重 “人道倫理”，試圖以易理指導修身；圖書派重 “宇宙生成”，試圖以圖式解釋萬物本源。這些流派並非相互割裂，而是在對立與融合中共同推動易學發展 —— 如朱熹調和象數與義理，王陽明將心學融入義理，皆體現了易學 “兼容並包” 的特質。</p><p>而京房、王弼、程頤、朱熹、邵雍等代表人物，雖治學路徑不同，卻共同完成了一件事：讓《易經》從遠古的占卜符號，演變為貫穿中國傳統哲學、倫理、文化的核心典籍。他們的著作與思想，不僅是易學傳承的 “路標”，更成為理解中國古代思維方式的重要鑰匙。</p><hr><h1 id="《易經》佔筮源流-古今主流方法與時空脈絡" tabindex="-1">《易經》佔筮源流：古今主流方法與時空脈絡 <a class="header-anchor" href="#《易經》佔筮源流-古今主流方法與時空脈絡" aria-label="Permalink to “《易經》佔筮源流：古今主流方法與時空脈絡”">​</a></h1><p>《易經》的佔筮傳統與典籍本身同樣古老，其方法隨時代思潮與社會需求不斷演變 —— 從先秦時期依託蓍草的莊重儀式，到唐宋後藉助錢幣、物象的簡便操作，每類方法的興替都烙印著鮮明的時代特徵。以下結合產生時間與流行階段，解析古今主流佔筮方法的核心內涵：</p><h3 id="一、大衍筮法-先秦至漢代的-正統蓍佔-約公元前-10-世紀-公元-3-世紀" tabindex="-1">一、大衍筮法：先秦至漢代的 &quot;正統蓍佔&quot;（約公元前 10 世紀 - 公元 3 世紀） <a class="header-anchor" href="#一、大衍筮法-先秦至漢代的-正統蓍佔-約公元前-10-世紀-公元-3-世紀" aria-label="Permalink to “一、大衍筮法：先秦至漢代的 &quot;正統蓍佔&quot;（約公元前 10 世紀 - 公元 3 世紀）”">​</a></h3><p>作為現存最早的系統佔筮法，大衍筮法的記載首見於《周易・繫辭上》，其起源可追溯至西周初年，與《周易》經傳的形成同步，是先秦貴族階層占卜決策的核心工具。</p><h4 id="核心操作" tabindex="-1">核心操作 <a class="header-anchor" href="#核心操作" aria-label="Permalink to “核心操作”">​</a></h4><p>以 50 根蓍草為 &quot;神物&quot;，先去除 1 根象徵 &quot;太極&quot;，剩餘 49 根按 &quot;分二、掛一、揲四、歸奇&quot; 四步演算：</p><ol><li><p><strong>分二</strong>：將 49 根蓍草隨機分為兩堆，代表 &quot;天地兩分&quot;；</p></li><li><p><strong>掛一</strong>：從右堆取出 1 根掛於指間，象徵 &quot;人立於天地間&quot;；</p></li><li><p><strong>揲四</strong>：左右兩堆分別以 4 根為一組數取（揲四），象徵 &quot;四季流轉&quot;；</p></li><li><p><strong>歸奇</strong>：將兩堆餘數與掛一之草合併，稱為 &quot;一變&quot;。</p></li></ol><p>重復三次演算（三變）得一爻，累計十八變生成六爻卦。根據爻的 &quot;老陰、老陽、少陰、少陽&quot; 屬性判斷吉凶，老陰、老陽為 &quot;變爻&quot;，需參考變卦解讀。</p><h4 id="流行與衰落" tabindex="-1">流行與衰落 <a class="header-anchor" href="#流行與衰落" aria-label="Permalink to “流行與衰落”">​</a></h4><p>先秦至西漢為鼎盛期，被視為溝通天人的 &quot;聖道&quot;，與當時祭祀文化、政治決策深度綁定。東漢後因操作繁瑣（完成一卦需數十分鐘），且受象數派簡化趨勢影響，逐漸被民間簡易方法取代，但始終被易學研究者視為 &quot;佔筮之本&quot;，朱熹在《周易本義》中曾詳細復原其流程。</p><h3 id="二、略筮法-漢代的-蓍佔簡化版-公元前-2-世紀-公元-3-世紀" tabindex="-1">二、略筮法：漢代的 &quot;蓍佔簡化版&quot;（公元前 2 世紀 - 公元 3 世紀） <a class="header-anchor" href="#二、略筮法-漢代的-蓍佔簡化版-公元前-2-世紀-公元-3-世紀" aria-label="Permalink to “二、略筮法：漢代的 &quot;蓍佔簡化版&quot;（公元前 2 世紀 - 公元 3 世紀）”">​</a></h3><p>略筮法是大衍筮法的簡化形態，產生於西漢中期，流行於兩漢民間與基層官吏群體，核心動因是解決大衍筮法 &quot;耗時費力&quot; 的弊端，適配日常事務的快速占卜需求。</p><h4 id="核心特徵" tabindex="-1">核心特徵 <a class="header-anchor" href="#核心特徵" aria-label="Permalink to “核心特徵”">​</a></h4><p>現存記載散見於《焦氏易林》《京氏易傳》等漢代文獻，具體操作已無完整遺存，據考據其核心是簡化 &quot;三變&quot; 流程：或減少蓍草數量（如用 36 根），或合併 &quot;揲四、歸奇&quot; 步驟，部分流派甚至以 &quot;擲蓍草定奇偶&quot; 替代複雜演算，本質是保留 &quot;蓍草為媒介&quot; 的傳統，同時追求效率提升。</p><h4 id="歷史地位" tabindex="-1">歷史地位 <a class="header-anchor" href="#歷史地位" aria-label="Permalink to “歷史地位”">​</a></h4><p>作為大衍筮法向後世簡易佔法的過渡形態，略筮法直接影響了京房象數派的占卜體系，其 &quot;簡化演算、注重實用&quot; 的思路，為後來錢筮法的誕生埋下伏筆。</p><h3 id="三、銅錢佔法-南北朝至現代的-民間主流-公元-5-世紀-至今" tabindex="-1">三、銅錢佔法：南北朝至現代的 &quot;民間主流&quot;（公元 5 世紀 - 至今） <a class="header-anchor" href="#三、銅錢佔法-南北朝至現代的-民間主流-公元-5-世紀-至今" aria-label="Permalink to “三、銅錢佔法：南北朝至現代的 &quot;民間主流&quot;（公元 5 世紀 - 至今）”">​</a></h3><p>銅錢佔法是大衍筮法的貨幣化替代形式，以錢幣拋擲替代蓍草演算，產生於南北朝時期，隋唐後逐步取代蓍佔成為民間主流，至今仍在廣泛使用。</p><h4 id="起源與定型" tabindex="-1">起源與定型 <a class="header-anchor" href="#起源與定型" aria-label="Permalink to “起源與定型”">​</a></h4><p>北齊學者黃慶、隋代李孟析已記載其雛形，唐代賈公彥在《儀禮疏》中明確其規則：&quot;以三少（錢的反面）為重錢，即九也；三多（正面）為交錢，即六也&quot;，標誌著方法定型。其興起與魏晉後錢幣流通普及、民間術數勃興直接相關，北宋《火珠林》將其與京房納甲說結合，形成 &quot;六爻納甲佔法&quot;，奠定後世發展基礎。</p><h4 id="核心操作-1" tabindex="-1">核心操作 <a class="header-anchor" href="#核心操作-1" aria-label="Permalink to “核心操作”">​</a></h4><p>主流為 &quot;三枚錢筮法&quot;，以乾隆通寶等方孔錢為首選（正面為 &quot;字&quot;，反面為 &quot;背&quot;）：</p><ol><li><p>雙手合十將三枚錢搖擲於卦盤，連續六次得六爻；</p></li><li><p>以 &quot;兩背一字&quot; 為少陽（—）、&quot;兩字一背&quot; 為少陰（--）、&quot;三背&quot; 為老陽（—○）、&quot;三字&quot; 為老陰（--×）；</p></li><li><p>老陽、老陰為變爻，結合本卦、變卦及納甲理論斷吉凶。</p></li></ol><p>明代後衍生出 &quot;六枚錢筮法&quot;，一次性擲出六爻，進一步簡化流程，但未取代三枚錢的主流地位。</p><h4 id="流行脈絡" tabindex="-1">流行脈絡 <a class="header-anchor" href="#流行脈絡" aria-label="Permalink to “流行脈絡”">​</a></h4><p>南北朝至唐代為發展期，宋元明清走向鼎盛，成為江湖術士、民間百姓占卜婚戀、生計的首選方法，朱熹在《朱子語類》中稱其 &quot;猶是漢人遺法&quot;，認可其傳統根源。近現代以來，雖歷經文化衝擊，仍在民俗領域持續流傳，是目前大眾最熟悉的《易經》佔筮形式。</p><h3 id="四、梅花易數-宋代至今的-物象起卦法-公元-11-世紀-至今" tabindex="-1">四、梅花易數：宋代至今的 &quot;物象起卦法&quot;（公元 11 世紀 - 至今） <a class="header-anchor" href="#四、梅花易數-宋代至今的-物象起卦法-公元-11-世紀-至今" aria-label="Permalink to “四、梅花易數：宋代至今的 &quot;物象起卦法&quot;（公元 11 世紀 - 至今）”">​</a></h3><p>梅花易數是脫離蓍草、錢幣的 &quot;心易&quot; 體系，相傳由北宋邵雍創立（實際成書於明末清初，託名邵雍），宋代興起後成為文人與民間並行的重要佔法。</p><h4 id="產生背景" tabindex="-1">產生背景 <a class="header-anchor" href="#產生背景" aria-label="Permalink to “產生背景”">​</a></h4><p>北宋圖書派易學興盛，邵雍提出 &quot;先天八卦&quot; 理論，為 &quot;即物起卦&quot; 提供了哲學基礎。其核心突破是擺脫固定媒介，以任意物象、時間、聲音等為起卦依據，適配宋代市民社會 &quot;無事不佔&quot; 的需求。</p><h4 id="核心操作-2" tabindex="-1">核心操作 <a class="header-anchor" href="#核心操作-2" aria-label="Permalink to “核心操作”">​</a></h4><p>以 &quot;先天八卦數&quot;（乾一、兌二、離三、震四、巽五、坎六、艮七、坤八）為基礎，常見起卦方式包括：</p><ol><li><p><strong>時間起卦</strong>：年月日數為上卦，年月日時總數為下卦，總數除六取動爻（如辰年 5 數 + 12 月 + 17 日 = 34，除 8 餘 2 為兌卦；加申時 9 數 = 43，除 8 餘 3 為離卦，得澤火革卦）；</p></li><li><p><strong>物象起卦</strong>：見老人屬乾卦，見南方屬離卦，結合方位、動靜組合成卦；</p></li><li><p><strong>字佔起卦</strong>：拆分漢字筆畫，前半為上卦，後半為下卦。</p></li></ol><p>斷卦核心為 &quot;體用生克&quot;—— 以主卦為 &quot;體&quot;（所佔之事），互卦、變卦為 &quot;用&quot;（影響因素），通過五行生剋關係判斷趨勢。</p><h4 id="流行特徵" tabindex="-1">流行特徵 <a class="header-anchor" href="#流行特徵" aria-label="Permalink to “流行特徵”">​</a></h4><p>宋代至今綿延不絕，明清時廣泛應用於風水、擇日、合婚等場景，甚至融入中醫臨床診斷。其 &quot;不動不佔、因事而佔&quot; 的靈活特質，使其成為文人修身與民間實用的 &quot;雙重工具&quot;，至今仍是易學愛好者入門的主流方法之一。</p><h3 id="五、佔筮方法演變的底層邏輯" tabindex="-1">五、佔筮方法演變的底層邏輯 <a class="header-anchor" href="#五、佔筮方法演變的底層邏輯" aria-label="Permalink to “五、佔筮方法演變的底層邏輯”">​</a></h3><p>從大衍筮法到梅花易數的千年流變，呈現三大趨勢：</p><ol><li><p><strong>媒介簡化</strong>：從 50 根蓍草到三枚銅錢，再到 &quot;萬物皆可起卦&quot;，反映出佔筮從 &quot;神聖儀式&quot; 向 &quot;日常工具&quot; 的下沈；</p></li><li><p><strong>理論融合</strong>：早期方法側重 &quot;天人感應&quot;，唐代後融入納甲、五行理論，宋代結合先天八卦，體現易學流派的交叉影響；</p></li><li><p><strong>主體性提升</strong>：從依賴蓍草 &quot;神意&quot; 到依託 &quot;本心感應&quot;（如梅花易數的 &quot;心易&quot;），暗合王陽明 &quot;心即易理&quot; 的思想脈絡。</p></li></ol><p>這些方法雖形式各異，卻共同延續著《易經》&quot;觀變知幾&quot; 的核心智慧 —— 無論是蓍草的莊重演算，還是錢幣的簡便拋擲，本質都是古人探索 &quot;天道&quot; 與 &quot;人事&quot; 關聯的思維實踐。</p><hr><h1 id="易道的核心思想" tabindex="-1">易道的核心思想 <a class="header-anchor" href="#易道的核心思想" aria-label="Permalink to “易道的核心思想”">​</a></h1><ul><li><strong>變易</strong>：萬物流轉。</li><li><strong>不易</strong>：背後有恆常規律。</li><li><strong>簡易</strong>：以簡馭繁，抓住關鍵。</li></ul><p>強調中正、時中、陰陽平衡，順勢而為。天人合一：觀察自然、修齊身心，以成就和諧行動。</p>',86)])])}const g=t(i,[["render",e]]);export{q as __pageData,g as default};
